/**
 * Pure helpers for the generation commands (quote → confirm). Exported through
 * src/index.ts so tests can exercise them against dist.
 */
/** Hard ceiling for generation.autoConfirmBelow - a misconfigured large value
 * must never silently authorize big spends. */
export declare const AUTO_CONFIRM_MAX = 200;
/**
 * Parse repeatable `--param key=value` flags. Split on the FIRST `=`;
 * a repeated key is an error, not a silent override (issue #1252's lesson).
 */
export declare function parseParamFlags(values: string[]): Record<string, string>;
/**
 * Merge `--param` escape-hatch values under the named flags (named flags win).
 * Values are passed through as strings/numbers/booleans by simple shape:
 * "true"/"false" → boolean, numeric → number, otherwise string. Semantic
 * validation happens server-side in the quote (the registry is the source of
 * truth).
 */
export declare function mergeGenerationParams(named: Record<string, unknown>, escape: Record<string, string>): Record<string, unknown>;
/** Strict integer parse for `--credits` / `--duration` style options. */
export declare function parseIntegerOption(name: string, value: string): number;
/**
 * Whether the CLI may auto-confirm this quote. The threshold is the human's
 * standing authorization (config generation.autoConfirmBelow, default 0 =
 * always ask); values above AUTO_CONFIRM_MAX are treated as AUTO_CONFIRM_MAX.
 */
export declare function shouldAutoConfirm(credits: number, threshold: number | undefined): boolean;
/** `aspectRatio` → `--aspect-ratio` for rendering param specs as flags. */
export declare function paramFlagName(name: string): string;
/** Compact `720p · 8s · camera_fixed` style summary of quote params. */
export declare function describeGenerationParams(params: Record<string, unknown>): string;
/** `92000ms` → `1m32s` for elapsed/progress labels. */
export declare function formatElapsed(milliseconds: number): string;
